public function __construct(
    private readonly {ModelName}Hooks $hooks,
    private readonly AuditService $auditService,
) {
}

public function create(array $data): {ModelName}
{
    return Capsule::transaction(function () use ($data) {
        $data = $this->hooks->beforeCreate($data);
        $model = {ModelName}::create($data);
        $this->hooks->afterCreate($model);
        $this->auditService->log(null, 'create', '{module}', 'Created {ModelName} #' . $model->id, null, null);
        return $model;
    });
}

