fixed_footer_macro_template.code:
{% macro render(paginator) %}
{% if paginator.lastPage() > 1 %}
<div class="p-4 border-t border-gray-200 flex flex-col sm:flex-row items-center justify-between gap-3">
    <p class="text-sm text-gray-500">Halaman <span class="font-bold text-gray-900">{{ paginator.currentPage() }}</span> dari <span class="font-bold text-gray-900">{{ paginator.lastPage() }}</span> ({{ paginator.total() }} Record)</p>
    <div class="flex items-center gap-1">
        {% if paginator.onFirstPage() %}
        <span class="px-3 py-1.5 text-sm text-gray-300 bg-white border border-gray-200 rounded-md cursor-not-allowed">Sebelumnya</span>
        {% else %}
        <a href="{{ paginator.previousPageUrl() }}" class="px-3 py-1.5 text-sm text-gray-500 bg-white border border-gray-300 rounded-md hover:bg-gray-50">Sebelumnya</a>
        {% endif %}

        {% set window = 2 %}
        {% set startPage = max(1, paginator.currentPage() - window) %}
        {% set endPage = min(paginator.lastPage(), paginator.currentPage() + window) %}

        {% if startPage > 1 %}
        <a href="{{ paginator.url(1) }}" class="px-3 py-1.5 text-sm text-gray-500 bg-white border border-gray-300 rounded-md hover:bg-gray-50">1</a>
        {% if startPage > 2 %}<span class="px-2 text-sm text-gray-400">&hellip;</span>{% endif %}
        {% endif %}

        {% for page in startPage..endPage %}
            {% if page == paginator.currentPage() %}
            <span class="px-3 py-1.5 text-sm font-medium text-white bg-green-800 rounded-md">{{ page }}</span>
            {% else %}
            <a href="{{ paginator.url(page) }}" class="px-3 py-1.5 text-sm text-gray-500 bg-white border border-gray-300 rounded-md hover:bg-gray-50">{{ page }}</a>
            {% endif %}
        {% endfor %}

        {% if endPage < paginator.lastPage() %}
        {% if endPage < paginator.lastPage() - 1 %}<span class="px-2 text-sm text-gray-400">&hellip;</span>{% endif %}
        <a href="{{ paginator.url(paginator.lastPage()) }}" class="px-3 py-1.5 text-sm text-gray-500 bg-white border border-gray-300 rounded-md hover:bg-gray-50">{{ paginator.lastPage() }}</a>
        {% endif %}

        {% if paginator.hasMorePages() %}
        <a href="{{ paginator.nextPageUrl() }}" class="px-3 py-1.5 text-sm text-gray-500 bg-white border border-gray-300 rounded-md hover:bg-gray-50">Berikutnya</a>
        {% else %}
        <span class="px-3 py-1.5 text-sm text-gray-300 bg-white border border-gray-200 rounded-md cursor-not-allowed">Berikutnya</span>
        {% endif %}
    </div>
</div>
{% else %}
<div class="p-4 border-t border-gray-200">
    <p class="text-sm text-gray-500">{{ paginator.total() }} Record</p>
</div>
{% endif %}
{% endmacro %}

