public function resetPassword(Request $request, Response $response, array $args): Response
{
    $user = User::findOrFail((int) $args['id']);
    $newPassword = bin2hex(random_bytes(6));

    $user->password = password_hash($newPassword, PASSWORD_BCRYPT);
    $user->must_change_password = true;
    $user->save();

    $this->session->getFlash()->add('success', "Password baru untuk {$user->username}: {$newPassword} (wajib diganti saat login berikutnya).");
    $this->auditService->log(null, 'reset_password', 'users', "Password direset untuk '{$user->username}'", null, null);

    return $response->withHeader('Location', '/users')->withStatus(302);
}

